import {api,escapeHtml as esc} from './business-api.mjs';
import {preparePersonaImage} from './persona-upload.mjs';
export function spaceHtml(posts,editable=false){
  if(!posts.length)return '<p class="space-empty">还没有图文展示</p>';
  return `<div class="space-posts">${posts.map(p=>`<article class="space-post">${p.imageUrl?`<img src="${esc(p.imageUrl)}" alt="个人图文展示" loading="lazy">`:''}<p>${esc(p.text)}</p><footer><time>${esc(new Date(p.createdAt).toLocaleDateString('zh-CN'))}</time>${editable?`<button type="button" data-remove-post="${esc(p.id)}">移除</button>`:''}</footer></article>`).join('')}</div>`;
}
export async function mountPersonaSpace(container,userId,{editable=false}={}){
  const {posts:initial}=await api(userId.startsWith('room:')?'/api/persona-space/room/'+encodeURIComponent(userId.slice(5)):'/api/persona-space/'+encodeURIComponent(userId));let posts=initial,imageContent=null,preparing=false;
  container.innerHTML=`<section class="persona-space"><header><h3>个人空间</h3><span>图文 · 登录用户可见</span></header>${editable?'<form class="space-compose"><label>分享照片或战绩<textarea name="text" maxlength="500" rows="3" placeholder="写下这一局的故事…"></textarea></label><div class="space-compose-actions"><label class="space-upload">添加图片<input type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" data-clear-image hidden>取消图片</button><button type="submit">发布图文</button></div><img class="space-draft" alt="待发布图片" hidden><p class="space-status" role="status"></p></form>':''}<div class="space-feed">${spaceHtml(posts,editable)}</div></section>`;
  const feed=container.querySelector('.space-feed'),form=container.querySelector('form'),status=container.querySelector('[role=status]');if(!editable)return;
  const submit=form.querySelector('[type=submit]'),draft=form.querySelector('.space-draft'),clear=form.querySelector('[data-clear-image]');
  clear.addEventListener('click',()=>{imageContent=null;draft.hidden=true;draft.removeAttribute('src');clear.hidden=true;});
  form.querySelector('[type=file]').addEventListener('change',async e=>{if(!e.target.files[0])return;preparing=true;submit.disabled=true;status.textContent='正在准备图片…';try{const image=await preparePersonaImage(e.target.files[0]);imageContent=image.content;draft.src=image.url;draft.hidden=false;clear.hidden=false;status.textContent='图片已准备。请勿上传他人的隐私或联系方式。';}catch(error){status.textContent=error.message;}finally{preparing=false;submit.disabled=false;e.target.value='';}});
  form.addEventListener('submit',async e=>{e.preventDefault();if(preparing||submit.disabled)return;submit.disabled=true;try{posts=(await api('/api/persona-space',{action:'publish',text:form.elements.text.value,imageContent})).posts;form.reset();clear.click();feed.innerHTML=spaceHtml(posts,true);status.textContent='已发布';}catch(error){status.textContent=error.message;}finally{submit.disabled=false;}});
  feed.addEventListener('click',async e=>{const button=e.target.closest('[data-remove-post]');if(!button||button.disabled)return;button.disabled=true;try{posts=(await api('/api/persona-space',{action:'delete',id:button.dataset.removePost})).posts;feed.innerHTML=spaceHtml(posts,true);status.textContent='已移除展示';}catch(error){status.textContent=error.message;button.disabled=false;}});
}
if(typeof document!=='undefined')document.addEventListener('click',async e=>{const button=e.target.closest('[data-persona-space]');if(!button)return;const target=button.parentElement.querySelector('.persona-space-target');if(!target)return;button.disabled=true;target.textContent='正在读取…';try{await mountPersonaSpace(target,button.dataset.personaSpace);button.hidden=true;}catch(error){target.textContent=error.message;}finally{button.disabled=false;}});
